traps.Trap02.txt:
//金兀术前的trap

	MoveScreen(*,*,*); //移到南宫灭和独孤剑之间
	Say("金兀术：大胆刺客，还不束手待缚！", 61);
	Say("独孤剑：金狗，今日你死期到了！", 5);
	Say("南宫灭：哼哼，就凭你……", 48);
	
	Say("金兵：啊——", 0);
	AddNpc("张琳心.ini",*,*,*);
	MoveScreen(*,*,*); //向下移动一点
	NpcGoto("张琳心",*,*);
	SetNpcDir("张琳心", *);
	Say("独孤剑：琳心！你为什么回来？！", 6);
	Say("张琳心：独孤大哥，我想得很清楚。如果你有什么不测，我也不会偷生于世……", 95);
	Say("独孤剑：琳儿……", 2);
	Say("南宫灭：原来是你们两个小鬼！", 47);
	Say("张琳心：不错，正是我们！", 21);
	SetNpcRes(独孤剑, " ");// 设回原来的外貌
	SetNpcRes(张琳心," "); //设回原来的外貌
	
	MoveScreen(*,*,*); //移到第一次移屏后的状况
	Say("金兀术：南宫先生认识他们？", 61);
	Say("南宫灭：这个，呃……", 49);
	Say("张琳心：他当然认得了。上次被我们打得落荒而逃，要不是我们饶他的狗命……如此大恩，他岂能忘记！", 21);
	Say("金兀术：南宫先生，果有此事？", 61);
	Say("南宫灭：……王爷，你自管去布置火炮，让老夫来收拾这两个跳梁小丑！", 48);
	Say("金兀术：好，这里就交给先生了。先生要快些来观看本王是怎么把岳家军捻为齑粉！哈哈哈哈……", 61);
	NpcGoto("金兀术",*,*);
	DelNpc("金兀术");
	
	Say("南宫灭：天堂大路你不走，地狱无门你自来投！哼哼，也免得老夫到处找你们。", 46);
	Say("独孤剑：呸！南宫狗贼，你作恶多端，今日便是你的死期！", 5);
	Say("张琳心：我要为父亲报仇！", 27);
	Say("南宫灭：不自量力，受死吧！", 47);
	SetNpcRelation("南宫灭",1);
	SetNpcRelation("金兵", 1); //金兵设为敌对，个数待定
	SetMapTrap(02,"");
	Return;

